import type { ChildProcess } from "node:child_process";
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdtempSync, readdirSync, rmSync, utimesSync, writeFileSync } from "node:fs";
import { hostname, tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { createPeerRegistry, parseProcStatStarttime } from "../src/registry.ts";
import type { PeerRecord, PeerRegistry } from "../src/types.ts";
import { generateTokens, keyFileNameFor, publishKey } from "../src/auth.ts";

const LIVE_PID = process.pid;
const DEAD_PID = 999999;

let peersDir: string;
let registry: PeerRegistry;
let secondLivePid = 0;
let liveChild: ChildProcess | undefined;
const tempDirs: string[] = [];

/** Fresh isolated registry directory per test — list() self-healing is stateful. */
function freshRegistry(): PeerRegistry {
	peersDir = mkdtempSync(join(tmpdir(), "pi-peers-registry-"));
	tempDirs.push(peersDir);
	registry = createPeerRegistry(peersDir);
	return registry;
}

/** Key file name for a record — now sourced from the auth export itself, so
 * fixtures and the registry sweep can never drift apart. */
function keyFileName(record: PeerRecord): string {
	return keyFileNameFor(record.pid, record.socketPath);
}

/** list() sweeps live-pid records whose auth key is missing: fixtures plant one. */
function plantKeyFor(record: PeerRecord): void {
	writeFileSync(join(peersDir, keyFileName(record)), "{}");
}

function makeRecord(pid: number, overrides: Partial<PeerRecord> = {}): PeerRecord {
	const record: PeerRecord = {
		version: 1,
		pid,
		sessionId: `session-${pid}`,
		cwd: "/tmp",
		name: `peer-${pid}`,
		nameSource: "user",
		formerNames: [],
		kind: "interactive",
		status: "idle",
		statusUpdatedAt: 1_000,
		startedAt: 900,
		pidDomain: "win32:testhost",
		socketPath: `\\\\.\\pipe\\LOCAL\\pi-peer-${String(pid).padStart(32, "0")}`,
		peerProtocol: 1,
		features: ["notify_idle"],
		...overrides,
	};
	// Production order is key-then-record; planting at construction keeps every
	// publish/direct-write fixture reachable under the key-consistency sweep.
	// Dead-pid fixtures are swept by the pid check before keys matter — planting
	// for them would only feed the orphan-key sweep an extra liveness probe.
	if (pid !== DEAD_PID) plantKeyFor(record);
	return record;
}

beforeAll(() => {
	// A second genuinely-live pid for multi-peer resolution cases.
	liveChild = spawn(process.execPath, ["-e", "process.stdin.resume()"], { stdio: ["pipe", "ignore", "ignore"] });
	if (typeof liveChild.pid !== "number") {
		throw new Error("failed to spawn helper child process");
	}
	secondLivePid = liveChild.pid;
});

afterAll(async () => {
	for (const dir of tempDirs) {
		rmSync(dir, { recursive: true, force: true });
	}
	if (liveChild) {
		liveChild.kill();
		// Await the real exit event (not a guessed delay) so the child pid is reaped.
		await new Promise<void>((done) => liveChild!.once("exit", () => done()));
	}
});

function recordFile(pid: number): string {
	return join(peersDir, `${pid}.json`);
}

function visibleFileNames(): string[] {
	return readdirSync(peersDir).sort();
}

/**
 * Liveness control for the invalid-field fixtures below: writes a VALID
 * LIVE_PID record (key planted by makeRecord), scans, and asserts the file
 * survives. The fixture pid being live is what makes those tests' deletion
 * assertions meaningful — with a dead pid the liveness sweep deletes
 * malformed records that parsePeerRecord wrongly accepted, so
 * validation-relaxation mutants would survive (MUTATION.md §4 #1).
 */
function assertValidRecordSurvivesScan(overrides: Partial<PeerRecord> = {}): void {
	const record = makeRecord(LIVE_PID, overrides);
	writeFileSync(recordFile(LIVE_PID), JSON.stringify(record));
	registry.list({ fresh: true });
	expect(existsSync(recordFile(LIVE_PID)), "valid LIVE_PID record must survive a scan").toBe(true);
}

/**
 * Count real probes for one pid without changing their verdicts: isAlive()
 * probes via process.kill(pid, 0), so wrapping the original (bound before
 * the spy — calling process.kill inside would recurse into the mock) keeps
 * real liveness semantics while making the probe count observable.
 */
function probeCountFor(pid: number): () => number {
	const probed: number[] = [];
	const realKill = process.kill.bind(process);
	vi.spyOn(process, "kill").mockImplementation(((target: number, signal?: number | string) => {
		if (target === pid) {
			probed.push(target);
		}
		return realKill(target, signal);
	}) as typeof process.kill);
	return () => probed.length;
}

